<template>
	<div id="om-flyout" :class="menu.active ? 'opened' : ''">
		<div id="om-flyout-items">
			<a
				v-for="(item, i) in items"
				:key="item.title"
				:href="item.url"
				:class="itemClasses(i)"
				:style="itemStyle(item.bgColor)"
				:onMouseOver="mouseOver(item.bgHoverColor)"
				:onMouseOut="mouseOut(item.bgColor)"
				target="_blank"
				rel="noopener noreferrer"
			>
				<div class="om-flyout-label">{{ item.title }}</div>
				<i :class="iconClass(item.icon)"></i>
			</a>
		</div>
		<a href="#" class="om-flyout-button om-flyout-head" @click.prevent="showOrHide">
			<div class="om-flyout-label">See Quick Links</div>
			<img :src="archie" alt="See Quick Links" />
		</a>
	</div>
</template>
<script lang="js">
import { mapGetters } from 'vuex'

export default {
	data () {
		const dotOrgSupport = this.$store.getters.showProUpsells;
		return {
			menu : {
				active : false,
				items  : [
					{
						title        : 'Suggest a Feature',
						url          : this.$urls.app('account/support/?topic=feature&utm_source=WordPress&utm_medium=QuickLinks&utm_campaign=Plugin'),
						icon         : 'fa-lightbulb-o',
						bgColor      : '#007FDB',
						bgHoverColor : '#3FA548',
					},
					{
						title        : 'Join Our Community',
						url          : 'https://www.facebook.com/groups/optinmonsterinnercircle/',
						icon         : 'fa-comments',
						bgColor      : '#007FDB',
						bgHoverColor : '#3FA548',
					},
					{
						title        : dotOrgSupport ? 'Visit Support Forums' : 'Support & Docs',
						url          : dotOrgSupport ? this.$urls.app('redirect/wp-plugin-support/') : this.$urls.docs('', 'QuickLinks'),
						icon         : 'fa-life-ring',
						bgColor      : '#007FDB',
						bgHoverColor : '#3FA548',
					},
					{
						title        : 'Upgrade to OptinMonster Pro',
						url          : this.$urls.upgrade({ utm_medium: 'QuickLinks' }),
						icon         : 'fa-star',
						bgColor      : '#F86D37',
						bgHoverColor : '#3FA548',
					},
				],
			},
		}
	},
	computed : {
		...mapGetters([ 'showProUpsells' ]),
		archie () {
			const images = require.context('../../assets/images/', false, /\.svg$/)
			return images(`./${this.menu.active ? '' : 'in'}active-archie.svg`)
		},
		items () {
			const items = [ ...this.menu.items ]
			if (!this.showProUpsells) {
				items.pop()
			}
			return items
		},
	},
	methods : {
		showOrHide () {
			this.menu.active = !this.menu.active
		},
		itemClasses (i) {
			return `om-flyout-button om-flyout-item om-flyout-item-${i}`
		},
		itemStyle (bgColor) {
			return `background-color: ${bgColor}`
		},
		mouseOver (bgHoverColor) {
			return `this.style.backgroundColor='${bgHoverColor}'`
		},
		mouseOut (bgColor) {
			return `this.style.backgroundColor='${bgColor}'`
		},
		iconClass (icon) {
			return `fa ${icon}`
		},
	},
};
</script>
<style scoped lang="scss">
